**The bug:** `decoded.exp < Date.now() / 1000` uses strict less-than, so when `exp === floor(now)` the token is accepted. The fix is `<=`.

**But there's a deeper issue:** `jwt.verify()` already validates expiry and throws `TokenExpiredError` before the manual check ever runs — making that check dead code that never triggers. The real problems are:

1. The manual expiry check is unreachable and uses wrong operator
2. The `catch` block swallows all errors with a generic message, losing useful context

Here's the corrected version:

```javascript
const jwt = require('jsonwebtoken');

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);

    // jwt.verify uses clockTimestamp >= payload.exp, so boundary is handled correctly.
    // Reject tokens with no expiry claim as a defense-in-depth measure.
    if (!decoded.exp) {
      return res.status(401).json({ error: 'Token missing expiry' });
    }

    req.user = decoded;
    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
    }
    if (err.name === 'JsonWebTokenError') {
      return res.status(401).json({ error: 'Invalid token' });
    }
    // Unexpected error (e.g. missing JWT_SECRET) — don't leak internals
    console.error('Auth middleware error:', err);
    return res.status(500).json({ error: 'Authentication error' });
  }
}

module.exports = authMiddleware;
```

**Summary of changes:**
- Removed the dead manual expiry check — `jwt.verify()` already uses `>=` comparison, correctly rejecting tokens at the exact expiry boundary
- Added a guard for tokens with no `exp` claim (which `jwt.verify` accepts by default)
- Split the catch block to distinguish `TokenExpiredError` vs `JsonWebTokenError` vs unexpected errors, returning appropriate status codes without leaking internal details
